#include "meeting_upload_protocol.h"
#include "meeting_receipt_json.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static meeting_manifest expected;static int step,scenario;
bool meeting_upload_manifest(FILE *f,const meeting_snapshot *s,bool ht,int64_t rt,uint8_t trust,meeting_manifest *out){(void)f;(void)s;(void)ht;(void)rt;(void)trust;*out=expected;return true;}
bool meeting_upload_manifest_cancel(FILE *f,const meeting_snapshot *s,bool ht,int64_t rt,uint8_t trust,meeting_manifest *out,meeting_cancel_fn cancelled,void *ctx){if(cancelled&&cancelled(ctx))return false;return meeting_upload_manifest(f,s,ht,rt,trust,out);}
bool meeting_upload_chunk(FILE *f,const meeting_snapshot *s,uint32_t seq,uint8_t *buf,size_t cap,size_t *len,uint8_t hash[32]){(void)f;(void)s;(void)seq;assert(cap>=3);memcpy(buf,"abc",3);memset(hash,7,32);*len=3;return true;}
static bool cancelled(void *ctx){(void)ctx;return false;}
static bool request(void *ctx,const char *method,const char *path,const char *type,const char *sha,const uint8_t *body,size_t body_len,int *status,char *response,size_t cap,size_t *len){(void)ctx;(void)type;(void)sha;(void)body;(void)body_len;if(!strcmp(method,"GET")&&strstr(path,"chunks-window")){if(scenario==5||scenario==6){int n=snprintf(response,cap,"{\"id\":\"%s\",\"first\":0,\"chunks\":[{\"seq\":0,\"size\":%d,\"digest\":\"0707070707070707070707070707070707070707070707070707070707070707\",\"valid\":true}]}",expected.id,scenario==6?4:3);assert(n>0&&(size_t)n<cap);*len=(size_t)n;*status=200;}else{*status=404;*len=0;}return true;}if(!strcmp(method,"GET")&&!strstr(path,"repair-status")){*status=404;*len=0;return true;}step++;*status=step==1?201:200;if(step==4&&scenario>=3){assert(!strcmp(method,"GET"));int n=snprintf(response,cap,"{\"id\":\"%s\",\"overall\":\"failed\",\"expectedCount\":1,\"missingCount\":%d,\"damagedSequences\":[0]}",expected.id,scenario==4?1:0);assert(n>0&&(size_t)n<cap);*len=(size_t)n;return true;}if(step==5&&scenario>=3){assert(!strcmp(method,"PUT"));memcpy(response,"{}",2);*len=2;return true;}if((step==3&&scenario<3)||(step==6&&(scenario==3||scenario==4))||(step==2&&scenario==5)){assert(!strcmp(method,"POST"));if(scenario==1)return false;int n=snprintf(response,cap,"{\"id\":\"%s\",\"committed\":true,\"manifest\":{\"count\":%d,\"bytes\":100,\"digest\":\"0707070707070707070707070707070707070707070707070707070707070707\",\"reason\":\"interrupted\",\"recordedAt\":null,\"timeTrust\":\"uncalibrated\"}}",expected.id,scenario==2?2:1);assert(n>0&&(size_t)n<cap);*len=(size_t)n;}else if(step==3&&scenario>=3){*status=409;const char *error="{\"error\":\"integrity\"}";*len=strlen(error);memcpy(response,error,*len);}else{assert(cap>=2);memcpy(response,"{}",2);*len=2;}return true;}
int main(void){memcpy(expected.id,"12345678-1234-4123-8123-123456789abc",37);expected.count=1;expected.bytes=100;expected.reason=3;memset(expected.digest,7,32);meeting_upload_transport t={NULL,cancelled,request};meeting_snapshot s={0};FILE *f=tmpfile();assert(f);assert(meeting_upload_run(f,&s,&expected,&t)==MEETING_UPLOAD_CONFIRMED);step=0;scenario=1;expected.id[35]='1';assert(meeting_upload_run(f,&s,&expected,&t)==MEETING_UPLOAD_FAILED);step=0;scenario=0;expected.id[35]='0';assert(meeting_upload_run(f,&s,&expected,&t)==MEETING_UPLOAD_CONFIRMED);step=0;scenario=2;expected.id[35]='2';assert(meeting_upload_run(f,&s,&expected,&t)==MEETING_UPLOAD_FAILED);step=0;scenario=3;expected.id[35]='3';assert(meeting_upload_run(f,&s,&expected,&t)==MEETING_UPLOAD_CONFIRMED&&step==6);step=0;scenario=4;expected.id[35]='4';assert(meeting_upload_run(f,&s,&expected,&t)==MEETING_UPLOAD_FAILED&&step==4);step=0;scenario=5;expected.id[35]='5';assert(meeting_upload_run(f,&s,&expected,&t)==MEETING_UPLOAD_CONFIRMED&&step==2);step=0;scenario=6;expected.id[35]='6';assert(meeting_upload_run(f,&s,&expected,&t)==MEETING_UPLOAD_FAILED&&step==1);fclose(f);return 0;}
